// ─── THE UNIT CARD, PINNED (T43 iron rule 4) ────────────────────────────────
//
// *"THE UNIT CARD DOES NOT MOVE. The card is a workshop sheet and its hidden
// lines are its value."*
//
// This renders ONE fixture cabinet's card deterministically — same params, same
// paper, same date, no clock and no design — so the string it produces can be
// compared byte for byte against `t43-unit-card-before.svg`, which was
// generated by this very file on the branch point (38a8483) before a line of
// T43 was written.
//
// It is an .mjs beside the fixture and not a test, because it has to be
// runnable against a checkout of ANY commit: that is what makes the BEFORE
// half of "before and after" a measurement rather than a memory.
//
//     node test/fixtures/t43-unit-card.mjs > before.svg     # on any checkout
//
import { DEFAULT_CABINET_PROFILE as P } from '../../src/engine/profile.js';
import { computeCabinet } from '../../src/engine/cabinet.js';
import { defaultParamsFor } from '../../src/engine/types.js';
import { unitCardSheet } from '../../src/engine/drawings/card.js';
import { sheetToSvg } from '../../src/engine/drawings/svg.js';

const params = {
  ...defaultParamsFor('BUDR', P),
  unit_num: '01',
  width: 600,
  plinth: true,
  shelves: 0,
  front_type: 'S',
};
const unit = { id: 'card-pin', type: 'BUDR', params };
const result = computeCabinet({ ...params }, P);
const sheet = unitCardSheet({
  result, unit, project: { name: 'T43 card pin' }, profile: P, format: 'A3', date: '20/08/2026',
});
export const T43_CARD_UNIT = unit;
export const T43_CARD_RESULT = result;

/** The card of the pinned fixture, as the string iron rule 4 compares. */
export function t43CardSvg(project = { name: 'T43 card pin' }) {
  return sheetToSvg(unitCardSheet({
    result, unit, project, profile: P, format: 'A3', date: '20/08/2026',
  }), { kind: 'unit-card' });
}

// Run directly → print it, so a BEFORE can be taken off any commit.
if (process.argv[1] && process.argv[1].endsWith('t43-unit-card.mjs')) {
  process.stdout.write(t43CardSvg());
}
